    internal static void ExactSeamGoal(bool holdAtSeam=false,bool exitOffset=false){
        var profile=PlayableProfile.RecastLayerQualification;var terrain=(StackedRampQualificationMap)profile.AuthoredMap;var geometry=new NavGeometry(terrain.HalfExtent,Array.Empty<NavObstacle>(),1);
        var goal=exitOffset?new NavLocation(new NavPoint(0,5),"upper"):new NavLocation(new NavPoint(-2,0),"ramp-support");double radius=profile.ExplorerCollisionRadius;Require(terrain.IsValidLocation(goal,radius),"source goal is not valid");
        var session=new NavigationSession(803,geometry,profile.Navigation,null,terrain){UsesRecastGroundRoutes=true};var kernel=new CertifiedRouteKernel();ulong before=RecastNative.sw_recast_allocation_count();
        try{
            session.MovementDelayActor=1;session.ConfigureMarch(profile.GroupMarchMaximumStretch,profile.Revision);session.Crowd.Add(1,exitOffset?new NavPoint(2,-9.8879238130678e-17):new NavPoint(-12,0),radius,PlayableUnitRules.Speed(profile,PlayableEntityKind.Explorer,false),profile.Navigation.TankTurnSpeed,exitOffset?(NavLocation?)new NavLocation(new NavPoint(2,-9.8879238130678e-17),"ramp-support"):null,canYield:true);
            var command=new PlayableCommand(803,1,"player-1",PlayableCommandKind.Move,new[]{1},goal.Position).WithResolvedLocation(goal);session.PrepareCommandGroup(command,1,0,1);
            bool accepted=session.MoveGroup(new[]{1},new[]{goal.Position});session.FinishCommandGroup(accepted,new[]{1});Require(accepted,"exact typed seam command refused");
            var binding=new PlayableRouteBinding(geometry,profile,session.Admission,session.RoutePort);for(int i=0;i<400&&session.AppliedResults<1;i++){kernel.Pump(binding,8);session.ApplyResults();}
            Require(session.AppliedResults==1&&session.InstalledExecutionFor(1)?.Corridor?.RecastPlan!=null,"exact seam did not install actual paid Ready");var actor=session.Crowd.Units.Single();var initial=actor.Position;long firstMotion=-1;int tick=0;bool held=false;
            for(;tick<1800&&actor.Outcome!=NavigationOutcome.Arrived;tick++){
                if(holdAtSeam&&!held&&actor.Position.Equals(goal.Position)&&actor.Location.SurfaceId=="lower"){
                    held=true;session.Stop(1,true);var location=actor.Location;for(int h=0;h<20;h++)session.Step(1d/30);
                    Require(actor.Held&&actor.Position.Equals(goal.Position)&&actor.Location.Equals(location)&&actor.Outcome==NavigationOutcome.Held,"HOLD consumed an idle semantic seam");
                    var resume=new PlayableCommand(803,2,"player-1",PlayableCommandKind.Move,new[]{1},goal.Position).WithResolvedLocation(goal);session.PrepareCommandGroup(resume,1,tick,2);bool moved=session.MoveGroup(new[]{1},new[]{goal.Position});session.FinishCommandGroup(moved,new[]{1});Require(moved,"held seam typed resume refused");
                    var resumed=new PlayableRouteBinding(geometry,profile,session.Admission,session.RoutePort);for(int r=0;r<400&&session.AppliedResults<2;r++){kernel.Pump(resumed,8);session.ApplyResults();}Require(session.AppliedResults==2,"held seam resume did not install Ready");
                }
                session.Step(1d/30);if(firstMotion<0&&!actor.Position.Equals(initial))firstMotion=tick+1;
            }
            Console.WriteLine(Newtonsoft.Json.JsonConvert.SerializeObject(new{Case=exitOffset?"actual2-valid-offset-exit-birth":holdAtSeam?"held-exact-authored-entry-goal":"exact-authored-entry-goal",Held=held,Source="normal typed command/paid kernel/real NavCrowd.Step; synchronous component only",Accepted=accepted,session.AppliedResults,kernel.RecastLongQueries,kernel.RecastAttachments,FirstMotion=firstMotion,Ticks=tick,Position=actor.Position,Location=actor.Location,Goal=goal,actor.Outcome,actor.Moving,actor.LastFailure,session.LastNavigationStepPath,session.LastOwnedMovementNullReason,session.LastOwnedMovementNullDetail,session.MovementDelayRecastReceipt,session.LastOwnedMovementComputation},Newtonsoft.Json.Formatting.Indented));
            if(holdAtSeam)Require(held,"HOLD case never observed lower exact seam");Require(firstMotion>0,"seam case had no actual motion");Require(actor.Location.SurfaceId==goal.SurfaceId&&actor.Outcome==NavigationOutcome.Arrived,"valid exact zero-XZ seam goal did not naturally arrive on its assigned semantic surface");
            Require(actor.Location.NameReference.Owner!=null&&(exitOffset||ReferenceEquals(actor.Location.NameReference.Owner,actor.GoalLocation.Value.NameReference.Owner)),"seam dropped owned canonical actor goal name");
            byte[] saved;using(var capture=session.CaptureState())saved=WorldWire.Pack(w=>WorldWire.Write(w,capture));
            NavigationSession restored=null;try{
                using(var state=WorldWire.Unpack(saved,WorldWire.ReadNavigationSessionState)){restored=new NavigationSession(803,geometry,profile.Navigation,null,terrain){UsesRecastGroundRoutes=true};restored.ConfigureMarch(profile.GroupMarchMaximumStretch,profile.Revision);restored.RestoreState(state);}
                var copy=restored.Crowd.Units.Single();Require(copy.Location.Equals(actor.Location)&&copy.Location.NameReference.Owner!=null&&copy.Outcome==NavigationOutcome.Arrived,"seam current restore lost semantic location/name/outcome");
                using(var capture=restored.CaptureState())Require(saved.SequenceEqual(WorldWire.Pack(w=>WorldWire.Write(w,capture))),"seam current codec bytes differ");
                Console.WriteLine("CURRENT SEAM NAME/EXACT CODEC PASS bytes="+saved.Length);
            }finally{restored?.ReleaseCommittedHostRoot();restored?.DestroyNavigationAuthority();}
        }finally{kernel.Clear();session.ReleaseCommittedHostRoot();session.DestroyNavigationAuthority();}
        Require(RecastNative.sw_recast_allocation_count()==before&&RecastNative.ReleaseFaults==0,"seam case leaked native owners");Console.WriteLine("EXACT SEAM PASS");
    }
    internal static void PartialContract()
    {
        Require(RecastGroupPreparation.TerminalStatus(RecastQueryStatus.Partial)==NavSolveStatus.Partial,"Partial aliases another result");
        Require(RecastGroupPreparation.TerminalStatus(RecastQueryStatus.ResourceFailure)==NavSolveStatus.CapacityExceeded&&RecastGroupPreparation.TerminalStatus(RecastQueryStatus.Unreachable)==NavSolveStatus.UnreachableInGraph,"terminal distinctions changed");
        var p=PlayableProfile.RecastLayerQualification;var terrain=(StackedRampQualificationMap)p.AuthoredMap;var geometry=new NavGeometry(terrain.HalfExtent,Array.Empty<NavObstacle>(),1);var budget=new NavigationRetentionBudget();
        var session=new NavigationSession(803,geometry,p.Navigation,null,terrain,budget,null){UsesRecastGroundRoutes=true};var kernel=new CertifiedRouteKernel();ulong native=RecastNative.sw_recast_allocation_count();
        try{
            session.ConfigureMarch(p.GroupMarchMaximumStretch,p.Revision);session.Crowd.Add(1,new NavPoint(-12,0),p.ExplorerCollisionRadius,PlayableUnitRules.Speed(p,PlayableEntityKind.Explorer,false),p.Navigation.TankTurnSpeed,canYield:true);
            var goal=new NavLocation(new NavPoint(0,5),"upper");var command=new PlayableCommand(803,1,"player-1",PlayableCommandKind.Move,new[]{1},goal.Position).WithResolvedLocation(goal);session.PrepareCommandGroup(command,1,0,1);bool ok=session.MoveGroup(new[]{1},new[]{goal.Position});session.FinishCommandGroup(ok,new[]{1});Require(ok,"contract request admission refused");
            var binding=new PlayableRouteBinding(geometry,p,session.Admission,session.RoutePort);NavigationAnswer actual=null;for(int i=0;i<400&&!session.Answers.TryPeek(out actual);i++)kernel.Pump(binding,8);Require(actual?.StorageOwner?.RequestOwner!=null,"no genuine paid request for standalone adapter test");
            Require(budget.TryOpenScope(NavigationPreparationKind.Capture,803,0,out var scope),"adapter scope refused");byte[] wire;NavigationHostAnswer partial=null;
            try{
                partial=NavigationHostAnswer.CreateTerminal(actual.StorageOwner.RequestOwner,NavSolveStatus.Partial,scope.OwnedReservation());Require(partial.Answer.RouteLength==0&&partial.Answer.Corridor==null&&partial.Answer.Status!=NavSolveStatus.Ready,"Partial became complete route");
                using(var scratch=NavStorageScratch.Reserve(scope.OwnedReservation(),2*1048576))using(var stream=new System.IO.MemoryStream(1048576)){using(var w=new System.IO.BinaryWriter(stream,System.Text.Encoding.UTF8,true))NavPhysicalBodyWire.WriteTo(w,partial,scope.OwnedReservation());wire=stream.ToArray();}
            }finally{partial?.ReleaseStorage();scope.Discard();}
            var cold=new NavigationRetentionBudget();Require(cold.TryOpenScope(NavigationPreparationKind.Decode,803,0,out var decode),"adapter decode refused");NavigationHostAnswer copy=null;
            try{using(var stream=new System.IO.MemoryStream(wire))using(var r=new System.IO.BinaryReader(stream))copy=(NavigationHostAnswer)NavPhysicalBodyWire.ReadFrom(r,decode.OwnedReservation(),NavigationHostBodyExtension.Instance);Require(copy.Answer.Status==NavSolveStatus.Partial&&copy.Answer.RouteLength==0&&copy.Answer.Corridor==null,"Partial BODY lost distinction");}
            finally{copy?.ReleaseStorage();decode.Discard();}Require(cold.PhysicalBytes==0&&cold.HeldBytes==0,"adapter decode leaked");
            Require(BitConverter.ToInt32(wire,13)==new NavPhysicalTag(NavPhysicalStorageKind.HostAnswer,value:NavPhysicalValueKind.HostPartialAnswerV1).Encoded,"unexpected root tag offset");var old=(byte[])wire.Clone();BitConverter.GetBytes(new NavPhysicalTag(NavPhysicalStorageKind.HostAnswer).Encoded).CopyTo(old,13);
            Require(cold.TryOpenScope(NavigationPreparationKind.Decode,803,1,out var reject),"old tag decode refused scope");bool refused=false;try{using(var stream=new System.IO.MemoryStream(old))using(var r=new System.IO.BinaryReader(stream)){var invalid=NavPhysicalBodyWire.ReadFrom(r,reject.OwnedReservation(),NavigationHostBodyExtension.Instance);invalid.ReleaseOwner();}}catch(ArgumentException){refused=true;}finally{reject.Discard();}Require(refused&&cold.PhysicalBytes==0&&cold.HeldBytes==0,"old answer tag reinterpreted Partial or leaked");
            byte[] actualState;using(var capture=session.CaptureState())actualState=WorldWire.Pack(w=>WorldWire.Write(w,capture));
            // Isolated serializer contract derived from an actual snapshot. This
            // DTO is never restored or submitted to an ordinary runtime.
            using(var dto=WorldWire.Unpack(actualState,WorldWire.ReadNavigationSessionState)){
                var answer=dto.AnswerMailbox.Single();answer.Status=NavSolveStatus.Partial;answer.Route=Array.Empty<NavPoint>();answer.Corridor=null;
                var actor=dto.Crowd.Units.Single();actor.FailedRequest=actual.Request.Request;actor.FailedOrder=actual.Request.Order;actor.FailedGroupId=actual.Request.MemberIdentity.GroupId;actor.FailedRevision=actual.Request.MemberIdentity.OrderRevision;actor.FailedGoal=actual.Request.GoalLocation;actor.LastFailure=NavigationOutcome.Rejected;
                dto.TechnicalFailures=new[]{new NavigationTechnicalFailureState{Entity=actor.Id,Request=actor.FailedRequest,Status=NavSolveStatus.Partial}};
                var extension=WorldWire.Pack(w=>GroupOrderWire.WriteExtension(w,dto));Require(BitConverter.ToInt32(extension,4)==13,"current status extension not thirteen");
                using(var stream=new System.IO.MemoryStream(extension))using(var r=new System.IO.BinaryReader(stream))GroupOrderWire.ReadExtension(r,dto);
                Require(dto.AnswerMailbox.Single().Status==NavSolveStatus.Partial&&dto.TechnicalFailures.Single().Status==NavSolveStatus.Partial,"Partial extension lost answer/technical cause");
                BitConverter.GetBytes(12).CopyTo(extension,4);bool oldRefused=false;try{using(var stream=new System.IO.MemoryStream(extension))using(var r=new System.IO.BinaryReader(stream))GroupOrderWire.ReadExtension(r,dto);}catch(ArgumentException){oldRefused=true;}Require(oldRefused,"old extension reinterpreted Partial");
            }
            Console.WriteLine("PARTIAL adapter mapping/paid terminal BODY/new tag/old-tag refusal/extension13 answer+technical cause/old12 refusal PASS; genuine native Partial query NotRun; no injected ordinary result");
        }finally{kernel.Clear();session.ReleaseCommittedHostRoot();session.DestroyNavigationAuthority();}
        Require(budget.PhysicalBytes==0&&budget.HeldBytes==0&&budget.ActiveScopes==0&&RecastNative.sw_recast_allocation_count()==native,"Partial contract leaked owners");
    }

    internal static void NearPeerContact()
    {
        var p=PlayableProfile.RecastLayerQualification;var terrain=(StackedRampQualificationMap)p.AuthoredMap;var geometry=new NavGeometry(terrain.HalfExtent,Array.Empty<NavObstacle>(),1);var session=new NavigationSession(803,geometry,p.Navigation,null,terrain){UsesRecastGroundRoutes=true};
        try{
            double r=p.ExplorerCollisionRadius;var a=new NavLocation(new NavPoint(0,3),"upper");var b=new NavLocation(new NavPoint(1.2,3),"upper");
            Require(1.2>=2*r&&1.2<=2*r+p.Navigation.ArrivalTolerance,"near peer source outside contact predicate");
            var one=session.Crowd.Add(1,a.Position,r,PlayableUnitRules.Speed(p,PlayableEntityKind.Explorer,false),p.Navigation.TankTurnSpeed,a,true);var two=session.Crowd.Add(2,b.Position,r,one.Speed,one.TurnSpeed,b,true);
            Require(session.Crowd.PhysicalSupportContact(one,two),"valid upper same-piece near peers lost physical support contact");
            var other=session.Crowd.Add(3,new NavPoint(-1.2,3),r,one.Speed,one.TurnSpeed,new NavLocation(new NavPoint(-1.2,3),"lower"),true);
            Require(!session.Crowd.PhysicalSupportContact(one,other),"different admitted layers acquired unsupported contact");
            Console.WriteLine("NEAR PEER same upper piece contact/different-layer conservative refusal PASS; helper source component, no broad cross-floor policy claim");
        }finally{session.ReleaseCommittedHostRoot();session.DestroyNavigationAuthority();}
    }

