        try{world=new PlayableAuthorityTick(config,804);Check(!world.Scheduler.Owners.Any(),"fresh world has AI owners");long tick=world.Tick;var bytes=world.CaptureBytes();using(var state=PlayableWorldState.Decode(bytes)){Check(state.Version==PlayableWorldState.CurrentVersion,"fresh world header is not current");Check(state.Binding.SequenceEqual(WorldWire.Binding(p)),"fresh binding differs");}
            restored=PlayableAuthorityTick.RestoreBytes(bytes,config);Check(restored.Tick==tick&&!restored.Scheduler.Owners.Any(),"restore changed tick/AI owner state");var recaptured=restored.CaptureBytes();Check(bytes.SequenceEqual(recaptured),"fresh current authority exact recapture differs");
            byte[] old;using(var state=PlayableWorldState.Decode(bytes)){state.Binding=state.Binding.Take(state.Binding.Length-924).ToArray();old=state.Encode();}bool refused=false;PlayableAuthorityTick invalid=null;try{invalid=PlayableAuthorityTick.RestoreBytes(old,p,config.Seed,config.SourceIdentity,config,Spacewars.Simulation.Ai.AiProfile.Initial,Array.Empty<string>(),negativeBudget);}catch(ArgumentException e){Check(e.Message.Contains("binding",StringComparison.OrdinalIgnoreCase),"prior binding refused for unrelated reason: "+e.Message);refused=true;}finally{if(invalid!=null){invalid.Stop();invalid.Domain.Navigation.ReleaseCommittedHostRoot();invalid.Domain.DestroyOwnedNavigation();}}
            Check(refused&&negativeBudget.PhysicalBytes==0&&negativeBudget.HeldBytes==0&&negativeBudget.ActiveScopes==0,"prior binding negative did not refuse cleanly");Console.WriteLine("FRESH AUTHORITY EPB1 PASS current exact capture/restore bytes="+bytes.Length+" tick="+tick+" noAIowners/noRuntime/noWorker; priorbindingrefused/negativeledger0");
        }finally{foreach(var w in new[]{restored,world})if(w!=null){w.Stop();w.Domain.Navigation.ReleaseCommittedHostRoot();w.Domain.DestroyOwnedNavigation();Check(w.Domain.Navigation.PhysicalHostBudget.PhysicalBytes==0&&w.Domain.Navigation.PhysicalHostBudget.HeldBytes==0&&w.Domain.Navigation.PhysicalHostBudget.ActiveScopes==0,"fresh world owner census nonzero");Console.WriteLine("FRESH AUTHORITY final physical/held/scopes=0");}Check(negativeBudget.PhysicalBytes==0&&negativeBudget.HeldBytes==0&&negativeBudget.ActiveScopes==0&&RecastNative.sw_recast_allocation_count()==native,"fresh authority/negative native or ledger leaked");Console.WriteLine("FRESH AUTHORITY native returned to baseline="+native);}
    }

